-- bricx.projects_guard (ADR 0075 D8, C1, C3): what a CHECK cannot hold,
-- for every role, the superuser included. id, org_id, created_by and
-- created_at never change; an archived project never changes again;
-- currency, reporting_currency and timezone change only while the row
-- was draft. Messages name no value. SQLSTATE P6004.
CREATE FUNCTION "bricx"."projects_guard"() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'a project keeps its identity'
      USING ERRCODE = 'P6004';
  END IF;
  IF OLD.status = 'archived' THEN
    RAISE EXCEPTION 'an archived project is final'
      USING ERRCODE = 'P6004';
  END IF;
  IF OLD.status <> 'draft'
     AND (NEW.currency IS DISTINCT FROM OLD.currency
          OR NEW.reporting_currency IS DISTINCT FROM OLD.reporting_currency
          OR NEW.timezone IS DISTINCT FROM OLD.timezone) THEN
    RAISE EXCEPTION 'currency, reporting currency and timezone change only while draft'
      USING ERRCODE = 'P6004';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "projects_guard" BEFORE UPDATE ON "bricx"."projects" FOR EACH ROW EXECUTE FUNCTION "bricx"."projects_guard"();
--> statement-breakpoint
-- bricx.sites_guard (ADR 0075 D15): id, org_id, project_id, created_by and
-- created_at never change; an archived site is final (no un-archive, no
-- edit). Every role. SQLSTATE P6005.
CREATE FUNCTION "bricx"."sites_guard"() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.project_id IS DISTINCT FROM OLD.project_id
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'a site keeps its identity'
      USING ERRCODE = 'P6005';
  END IF;
  IF OLD.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'an archived site is final'
      USING ERRCODE = 'P6005';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "sites_guard" BEFORE UPDATE ON "bricx"."sites" FOR EACH ROW EXECUTE FUNCTION "bricx"."sites_guard"();
--> statement-breakpoint
-- access_grants_immutable v2 (ADR 0075, amending ADR 0067; C9): site_id
-- is fixed like scope_id. Otherwise as 0007 wrote it.
CREATE OR REPLACE FUNCTION "bricx"."access_grants_immutable"() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.permission IS DISTINCT FROM OLD.permission
     OR NEW.scope_id IS DISTINCT FROM OLD.scope_id
     OR NEW.site_id IS DISTINCT FROM OLD.site_id
     OR NEW.reason IS DISTINCT FROM OLD.reason
     OR NEW.granted_by IS DISTINCT FROM OLD.granted_by
     OR NEW.starts_at IS DISTINCT FROM OLD.starts_at
     OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'an access grant is immutable but for its end'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF (NEW.revoked_at IS DISTINCT FROM OLD.revoked_at
      OR NEW.revoked_by IS DISTINCT FROM OLD.revoked_by
      OR NEW.expired_at IS DISTINCT FROM OLD.expired_at)
     AND (OLD.revoked_at IS NOT NULL OR OLD.revoked_by IS NOT NULL
          OR OLD.expired_at IS NOT NULL
          OR (NEW.revoked_at IS NOT NULL AND NEW.expired_at IS NOT NULL)) THEN
    RAISE EXCEPTION 'an access grant ends once'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END
$$;
